#!/bin/sh
# Regenerates the rainbow fish cluster charts. Run from the repo root.
K=~/.claude/skills/fishcare-page/scripts; D=assets/guides/rainbowfish; mkdir -p $D
C(){ python3 $K/images.py chart "$@" 2>&1 | grep wrote; }
C --out $D/rainbow-fish-care-at-a-glance.svg --title "Rainbow fish care at a glance: what every Melanotaenia needs" --subtitle "Peaceful, fast, colourful schoolers from Australia and New Guinea. Space and a group matter most." --row "Group size|6 or more|schools; colour only shows in a group" --row "Tank size|30–55+ gallons, 3–4 ft|long tanks for constant swimming" --row "Temperature|74–79°F (23–26°C)|most species; praecox 75–82°F" --row "pH / hardness|7.0–8.0 / 8–15 dGH|hard, alkaline, stable" --row "Ammonia / nitrite|0 ppm|nitrate under 20 ppm" --row "Diet|flake, pellets, frozen, some veg|small mouths, feed 2× daily" --row "Lifespan|5–8 years|boesemani to 10" --alt "Rainbow fish care chart: keep 6 or more, 30 to 55 gallon tank at least 3 feet long, 74 to 79 F, pH 7 to 8, hardness 8 to 15 dGH, zero ammonia and nitrite, varied small food twice daily, 5 to 8 year lifespan" --footer "Each number is expanded on a page of the rainbow fish care series."
C --out $D/rainbow-fish-tank-size-chart.svg --title "Rainbow fish tank size by species group" --subtitle "Minimum for a school of six. Length first: rainbowfish sprint the full tank all day." --row "Dwarf: praecox, threadfin, forktail|20–30 gal · 30 in|2–2.5 in adults, 8–10 fish" --row "Medium: boesemani, turquoise, celebes|40–55 gal · 3–4 ft|3–4 in adults, 6–8 fish" --row "Large: Australian, red, parkinsoni|55–75 gal · 4 ft|4–6 in adults, 6+ fish" --row "Two species together|75+ gal · 4 ft|two schools of 6" --row "Breeding trio|20 gal · 24 in|1 male, 2 females, mop" --alt "Rainbow fish tank size chart: 20 to 30 gallons for dwarf rainbowfish, 40 to 55 gallons and 3 to 4 feet for boesemani and turquoise, 55 to 75 gallons for Australian and red rainbowfish, 75 gallons for two species" --footer "A 10-gallon tank suits no rainbowfish school, not even the dwarf neon."
C --out $D/rainbow-fish-water-parameters.svg --title "Rainbow fish water parameters: hard, alkaline and steady" --subtitle "Most Melanotaenia come from mineral-rich rivers and lakes. Soft acidic water is the classic mistake." --row "Temperature|74–79°F (23–26°C)|praecox and red: 75–82°F" --row "pH|7.0–8.0|below 6.8 colour fades" --row "GH|8–15 dGH|crushed coral in soft water" --row "KH|5–12 dKH|holds the pH steady" --row "Ammonia / nitrite|0 ppm|always" --row "Nitrate|<20 ppm|25% weekly change" --row "Flow|moderate|they love current" --alt "Rainbow fish water parameters chart: 74 to 79 F, pH 7 to 8, GH 8 to 15, KH 5 to 12, zero ammonia and nitrite, nitrate under 20 ppm, moderate flow"
C --out $D/rainbow-fish-feeding-schedule.svg --title "Rainbow fish food and feeding schedule" --subtitle "Small mouths, fast metabolism, surface and midwater feeders. Variety brings out the colour." --row "Flake or micro pellets|daily, 2 feeds|the staple; small enough to swallow" --row "Frozen bloodworm, daphnia, brine|3–4× per week|thaw and rinse; conditioning" --row "Live daphnia, brine shrimp|weekly or for breeding|triggers spawning" --row "Spirulina flake, blanched spinach|2× per week|they graze algae in the wild" --row "Colour-enhancing (astaxanthin)|3× per week|reds and oranges in boesemani" --alt "Rainbow fish food chart: small flake or micro pellets twice daily, frozen bloodworm and daphnia three to four times a week, live food weekly, spirulina and vegetables twice a week, colour-enhancing food" --footer "Feed only what is gone in 2 minutes; rainbowfish beg and are easy to overfeed."
C --out $D/rainbow-fish-size-lifespan.svg --title "Rainbow fish size and lifespan by species" --subtitle "Adult length, then years in a well-kept tank." --row "Dwarf neon (praecox)|2–2.5 in|4–5 years" --row "Threadfin, forktail, Gertrude's|1.5–2.5 in|3–5 years" --row "Celebes rainbowfish|3 in|5 years" --row "Boesemani|3.5–4.5 in|6–10 years" --row "Turquoise (lacustris)|4–4.5 in|6–8 years" --row "Australian, splendid|4–5 in|6–8 years" --row "Red (Glossolepis incisus)|5–6 in|8 years" --alt "Rainbow fish size and lifespan chart: dwarf neon 2 to 2.5 inches and 4 to 5 years, boesemani 3.5 to 4.5 inches and 6 to 10 years, turquoise 4 to 4.5 inches, Australian 4 to 5 inches, red rainbowfish 5 to 6 inches and 8 years"
C --out $D/rainbow-fish-breeding.svg --title "Rainbow fish breeding: the egg-scatterer routine" --subtitle "Easy to spawn, slow to raise. The fry are the work, not the eggs." --row "Sexing|males deeper, brighter|females slimmer, paler, shorter fins" --row "Conditioning|live food 1–2 weeks|1 male, 2 females" --row "Spawning|daily at dawn|10–50 eggs a day onto a mop or moss" --row "Eggs|adhesive, 1 mm|hatch in 7–10 days at 77°F" --row "Fry|infusoria first|baby brine shrimp from day 5–7" --row "Growth|slow|1 inch at 3 months; colour at 6–9" --alt "Rainbow fish breeding chart: males deeper and brighter, condition with live food, daily dawn spawning of 10 to 50 adhesive eggs on a mop, hatch in 7 to 10 days, fry need infusoria then baby brine shrimp, colour at 6 to 9 months"
C --out $D/rainbow-fish-tank-mates.svg --title "Rainbow fish tank mates: fast, peaceful and hard-water" --subtitle "Rainbowfish suit almost any peaceful community that can keep up with them." --row "Tetras, rasboras, danios, barbs|✓ excellent|other schoolers; skip fin-nippers" --row "Corydoras, plecos, loaches|✓ excellent|different level of the tank" --row "Guppies, platies, mollies|✓ good|share hard water; guppies outcompeted" --row "Gouramis, angelfish, rams|✓ in 55+ gal|angelfish may eat dwarf rainbows" --row "Discus|✗ careful|too warm, too slow a feeder" --row "Betta|✗|outpaced and stressed" --row "Goldfish, large cichlids|✗|wrong temperature; bullies" --alt "Rainbow fish tank mates chart: tetras, rasboras, danios, corydoras, plecos, guppies, platies and gouramis are good; discus, betta, goldfish and large cichlids are not"
C --out $D/rainbow-fish-behavior.svg --title "Rainbow fish behavior: what each signal means" --subtitle "Fast, busy, sociable fish. Most 'problems' are a school that is too small." --row "Sprinting, chasing at dawn|normal|males sparring and courting" --row "Bold head stripe, bright colour|normal|dominant male displaying" --row "Pale, drab colour|stress or too few fish|school of 6+, check water" --row "Hiding all day|new, bullied, or alone|add to the group; add cover" --row "Jumping|startle or spawning chase|tight lid, dim the lights on" --row "Flashing on decor|parasite or pH swing|test water; look for spots" --row "On the bottom, clamped|illness|isolate; see diseases page" --alt "Rainbow fish behavior chart: sprinting and dawn chasing are normal, bold head stripe is a displaying male, pale colour means stress or too small a school, hiding means alone or bullied, jumping needs a lid, flashing means parasites"
C --out $D/rainbow-fish-diseases-chart.svg --title "Rainbow fish diseases: the ones that actually kill rainbowfish" --subtitle "Rainbowfish are hardy, but three conditions are near-untreatable once established." --row "Columnaris (saddleback)|grey saddle, frayed fins|fast; antibiotics, cooler water" --row "Fish TB (Mycobacterium)|wasting, bent spine|no cure; cull, disinfect" --row "Ich|salt-grain white spots|86°F + salt, or meds" --row "Velvet|gold dust, scratching|copper or salt; dim lights" --row "Bloat / dropsy|swollen belly, raised scales|Epsom salt, isolate" --row "Internal parasites|wasting, clear faeces|metronidazole or levamisole" --alt "Rainbow fish diseases chart: columnaris saddle and frayed fins, fish tuberculosis wasting and bent spine, ich white spots, velvet gold dust, bloat and dropsy, internal parasites causing wasting" --footer "Buy from tanks with no thin or crooked fish. Quarantine 3–4 weeks; mycobacterium arrives with the fish."
C --out $D/rainbow-fish-tank-size-calculation.svg --title "How the rainbow fish tank size calculator works" --subtitle "Starts from the species' school minimum, then scales for group size, extra species and plants." --row "1. Species minimum|20 / 40 / 55 gal|for a school of 6 at adult size" --row "2. Group size|+12% per extra fish|beyond 6" --row "3. Second species|+70% of its minimum|two schools share swimming room" --row "4. Length check|30 / 36 / 48 in|dwarf / medium / large" --row "Result|gallons and length|next standard tank up" --alt "Rainbow fish tank size calculator diagram: species minimum of 20, 40 or 55 gallons for six fish, plus 12 percent per extra fish, plus 70 percent of a second species minimum, checked against 30, 36 or 48 inch tank length"
C --out $D/rainbow-fish-types-chart.svg --title "Types of rainbow fish: the 12 you will find for sale" --subtitle "Three size bands, two genera that matter, one care recipe." --row "Dwarf (under 2.5 in)|praecox, threadfin, forktail|20–30 gal, 8+ fish" --row "Medium (3–4.5 in)|boesemani, turquoise, celebes|40–55 gal, 6+ fish" --row "Large (4–6 in)|Australian, red, parkinsoni|55–75 gal, 6+ fish" --row "Hardiest|boesemani, Australian, turquoise|good first rainbowfish" --row "Fussiest|threadfin, celebes, Madagascar|need small food, stable water" --alt "Types of rainbow fish chart: dwarf praecox, threadfin and forktail under 2.5 inches; medium boesemani, turquoise and celebes 3 to 4.5 inches; large Australian, red and parkinsoni 4 to 6 inches; boesemani and Australian hardiest"
